const cfg = $('Set config: video URL, key & email').first().json;
const focus = cfg.focus || '';
let transcript = $json.content;
if (Array.isArray(transcript)) transcript = transcript.map((s) => s.text).join(' ');
transcript = String(transcript || '').slice(0, Number(cfg.maxChars) || 45000);
const schema = { type: 'object', additionalProperties: false, required: ['title','tldr','key_takeaways','notes','action_items'], properties: {
  title: { type: 'string' }, tldr: { type: 'string' },
  key_takeaways: { type: 'array', items: { type: 'string' } },
  notes: { type: 'string' }, action_items: { type: 'array', items: { type: 'string' } } } };
const system = 'You are an expert note-taker. Turn this YouTube transcript into notes a busy person can act on WITHOUT watching the video. Be faithful to the transcript; do not invent facts not present.';
const user = 'Return: title (best guess of the video topic), tldr (2-3 sentences), key_takeaways (5-8 crisp bullets), notes (well-structured markdown with subheadings), action_items (concrete things to do, or empty).'
  + (focus ? ' The reader especially cares about: ' + focus + '. Weight the notes toward that.' : '')
  + '\n\n=== TRANSCRIPT ===\n' + transcript;
return [{ json: { body: {
  model: cfg.model || 'claude-haiku-4-5', max_tokens: 2000, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

const cfg = $('Set config: video URL, key & email').first().json;
const blocks = $json.content || [];
let out = {};
try { out = JSON.parse((blocks.find((b) => b.type === 'text') || {}).text || '{}'); } catch (e) {}
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const md = (s) => esc(s)
  .replace(/^### (.*)$/gm, '<h4>$1</h4>').replace(/^## (.*)$/gm, '<h3>$1</h3>').replace(/^# (.*)$/gm, '<h3>$1</h3>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/^\s*[-*] (.*)$/gm, '<li>$1</li>').replace(/(<li>[\s\S]*?<\/li>)/g, '<ul>$1</ul>')
  .replace(/\n{2,}/g, '<br><br>').replace(/\n/g, '<br>');
const list = (a) => Array.isArray(a) && a.length ? '<ul>' + a.map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '';
const html =
  '<div style="font-family:system-ui,Arial;max-width:760px;margin:0 auto;text-align:left">' +
  '<h2>' + esc(out.title) + '</h2>' +
  (out.tldr ? '<p style="font-size:15px;color:#333"><strong>TL;DR:</strong> ' + esc(out.tldr) + '</p>' : '') +
  (out.key_takeaways && out.key_takeaways.length ? '<h3>Key takeaways</h3>' + list(out.key_takeaways) : '') +
  (out.notes ? '<h3>Notes</h3><div>' + md(out.notes) + '</div>' : '') +
  (out.action_items && out.action_items.length ? '<h3>Action items</h3>' + list(out.action_items) : '') +
  '<p style="color:#999;font-size:12px;margin-top:20px">Generated from the video transcript via nocode.expert.</p></div>';
return [{ json: { title: out.title || 'Video notes', html, deliverTo: cfg.email } }];
